PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', purpose TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','active','archived')), version INTEGER NOT NULL, parent_template_id TEXT, immutable INTEGER NOT NULL DEFAULT 0 CHECK(immutable IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_template_fields (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES context_templates(id) ON DELETE CASCADE, field_key TEXT NOT NULL, label TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', value_type TEXT NOT NULL CHECK(value_type IN('text','long_text','boolean','single_choice','multi_choice','integer','number','date','datetime','duration_minutes','scale')), required INTEGER NOT NULL CHECK(required IN(0,1)), display_order INTEGER NOT NULL, options_json TEXT NOT NULL DEFAULT '[]', minimum_value REAL, maximum_value REAL, unit TEXT, analysis_role TEXT, analysis_role_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(analysis_role_confirmed IN(0,1)), analysis_usage TEXT NOT NULL DEFAULT 'excluded' CHECK(analysis_usage IN('condition','outcome','both','excluded')), analysis_merge_allowed INTEGER NOT NULL DEFAULT 0 CHECK(analysis_merge_allowed IN(0,1)), sharing_default TEXT NOT NULL CHECK(sharing_default IN('always','purpose_only','private','never')), sensitivity TEXT NOT NULL CHECK(sensitivity IN('normal','sensitive','highly_sensitive')), reason TEXT NOT NULL, UNIQUE(template_id,field_key), UNIQUE(template_id,display_order)) STRICT;
CREATE TABLE IF NOT EXISTS context_entries (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES context_templates(id), template_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_values (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES context_entries(id) ON DELETE CASCADE, field_key TEXT NOT NULL, value_json TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('user_input','integration_import','manual_import')), source_id TEXT, user_confirmed INTEGER NOT NULL CHECK(user_confirmed IN(0,1)), reviewed_at TEXT, reconfirm_after TEXT, last_reconfirmed_at TEXT, sharing TEXT NOT NULL CHECK(sharing IN('always','purpose_only','private','never')), sensitivity TEXT NOT NULL CHECK(sensitivity IN('normal','sensitive','highly_sensitive')), current_revision_id TEXT, lifecycle_state TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle_state IN('active','retracted')), recorded_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(entry_id,field_key)) STRICT;
CREATE TABLE IF NOT EXISTS context_value_revisions (id TEXT PRIMARY KEY, value_id TEXT NOT NULL REFERENCES context_values(id) ON DELETE CASCADE, entry_id TEXT NOT NULL REFERENCES context_entries(id) ON DELETE CASCADE, field_key TEXT NOT NULL, value_json TEXT NOT NULL, change_type TEXT NOT NULL CHECK(change_type IN('initial','correction','state_change','exception','reaffirmation','retraction')), reason TEXT NOT NULL, valid_from TEXT, valid_to TEXT, sharing TEXT NOT NULL CHECK(sharing IN('always','purpose_only','private','never')), sensitivity TEXT NOT NULL CHECK(sensitivity IN('normal','sensitive','highly_sensitive')), supersedes_revision_id TEXT, source_id TEXT, source_content_hash TEXT, user_confirmed INTEGER NOT NULL CHECK(user_confirmed IN(0,1)), confirmed_at TEXT, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_sharing_purposes (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_value_purposes (value_id TEXT NOT NULL REFERENCES context_values(id) ON DELETE CASCADE, purpose_id TEXT NOT NULL REFERENCES context_sharing_purposes(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(value_id,purpose_id)) STRICT;
CREATE TABLE IF NOT EXISTS context_profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, target TEXT NOT NULL, purpose_id TEXT REFERENCES context_sharing_purposes(id), detail_level TEXT NOT NULL CHECK(detail_level IN('short','standard','detailed')), maximum_characters INTEGER, maximum_tokens INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_profile_fields (profile_id TEXT NOT NULL REFERENCES context_profiles(id) ON DELETE CASCADE, template_id TEXT NOT NULL, field_key TEXT NOT NULL, PRIMARY KEY(profile_id,template_id,field_key)) STRICT;
CREATE TABLE IF NOT EXISTS context_conflicts (id TEXT PRIMARY KEY, field_keys_json TEXT NOT NULL, value_ids_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('unresolved','keep_latest','keep_both','resolved_manually')), created_at TEXT NOT NULL, resolved_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS context_exports (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES context_profiles(id), purpose_id TEXT REFERENCES context_sharing_purposes(id), destination TEXT NOT NULL DEFAULT '', format TEXT NOT NULL CHECK(format IN('markdown','json','agents','chatgpt')), target TEXT NOT NULL DEFAULT 'markdown_manual', preview_fingerprint TEXT, maximum_tokens INTEGER, content TEXT NOT NULL, manifest_json TEXT NOT NULL DEFAULT '{}', omitted_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS privacy_audit_logs (id TEXT PRIMARY KEY, action TEXT NOT NULL, summary_json TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS context_values_entry_idx ON context_values(entry_id,field_key);
CREATE INDEX IF NOT EXISTS context_values_reconfirm_idx ON context_values(reconfirm_after) WHERE user_confirmed=1 AND lifecycle_state='active';
CREATE INDEX IF NOT EXISTS context_value_purposes_purpose_idx ON context_value_purposes(purpose_id,value_id);
CREATE INDEX IF NOT EXISTS context_value_revisions_value_idx ON context_value_revisions(value_id,created_at DESC);
CREATE INDEX IF NOT EXISTS context_value_revisions_entry_field_idx ON context_value_revisions(entry_id,field_key,created_at DESC);
CREATE TABLE IF NOT EXISTS privacy_safe_delete_plans (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES context_entries(id) ON DELETE CASCADE, confirmation_token TEXT NOT NULL, summary_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('planned','executed','cancelled')), created_at TEXT NOT NULL, executed_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS context_documents (id TEXT PRIMARY KEY, file_path TEXT NOT NULL UNIQUE, title TEXT NOT NULL, recorded_at TEXT NOT NULL, source_updated_at TEXT NOT NULL, content_hash TEXT NOT NULL, file_size INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT) STRICT;
CREATE INDEX IF NOT EXISTS context_documents_recorded_at_idx ON context_documents(recorded_at DESC);
CREATE VIRTUAL TABLE IF NOT EXISTS context_document_fts USING fts5(document_id UNINDEXED,title,body);
CREATE TABLE IF NOT EXISTS context_entry_candidates (entry_id TEXT PRIMARY KEY REFERENCES context_entries(id) ON DELETE CASCADE, document_id TEXT NOT NULL REFERENCES context_documents(id) ON DELETE CASCADE, source_content_hash TEXT NOT NULL, provider TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_value_reviews (id TEXT PRIMARY KEY, value_id TEXT NOT NULL REFERENCES context_values(id) ON DELETE CASCADE, entry_id TEXT NOT NULL REFERENCES context_entries(id) ON DELETE CASCADE, field_key TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN('accepted','edited_and_accepted','rejected','unknown')), reason TEXT NOT NULL, reviewed_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS context_value_reviews_value_idx ON context_value_reviews(value_id,reviewed_at DESC);
CREATE TABLE IF NOT EXISTS context_provenance (id TEXT PRIMARY KEY, subject_type TEXT NOT NULL CHECK(subject_type IN('document','entry','value','template','export','integration_import','backup')), subject_id TEXT NOT NULL, event_type TEXT NOT NULL, actor_type TEXT NOT NULL CHECK(actor_type IN('user','local_ai','integration','system')), source_ref TEXT, source_content_hash TEXT, provider_id TEXT, model TEXT, payload_hash TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS context_provenance_subject_idx ON context_provenance(subject_type,subject_id,created_at DESC);
CREATE INDEX IF NOT EXISTS context_provenance_source_idx ON context_provenance(source_ref,created_at DESC);
CREATE TABLE IF NOT EXISTS context_external_ai_consents (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN('document','field')), provider_id TEXT NOT NULL, destination_host TEXT NOT NULL, document_id TEXT NOT NULL DEFAULT '', template_id TEXT NOT NULL DEFAULT '', field_key TEXT NOT NULL DEFAULT '', granted_at TEXT NOT NULL, revoked_at TEXT, UNIQUE(scope,provider_id,destination_host,document_id,template_id,field_key)) STRICT;
CREATE INDEX IF NOT EXISTS context_external_ai_consents_active_idx ON context_external_ai_consents(provider_id,destination_host,scope,revoked_at);
CREATE TABLE IF NOT EXISTS integration_template_requests (id TEXT PRIMARY KEY, source_system TEXT NOT NULL, source_request_id TEXT NOT NULL, source_reference_id TEXT, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','template_created','rejected')), template_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source_system,source_request_id)) STRICT;
CREATE INDEX IF NOT EXISTS integration_template_requests_status_idx ON integration_template_requests(status,created_at DESC);
CREATE TABLE IF NOT EXISTS integration_import_records (id TEXT PRIMARY KEY, source_system TEXT NOT NULL, source_import_id TEXT NOT NULL, source_reference_id TEXT, payload_json TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN('pending','accepted','edited_and_accepted','held','rejected')), target_template_id TEXT, target_field_key TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source_system,source_import_id)) STRICT;
CREATE INDEX IF NOT EXISTS integration_import_records_decision_idx ON integration_import_records(decision,created_at DESC);
CREATE TABLE IF NOT EXISTS integration_clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, permissions_json TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_backups (id TEXT PRIMARY KEY, file_name TEXT NOT NULL UNIQUE, file_size INTEGER NOT NULL, file_hash TEXT NOT NULL, created_at TEXT NOT NULL, verified_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS context_restore_plans (id TEXT PRIMARY KEY, backup_id TEXT NOT NULL REFERENCES context_backups(id), confirmation_token TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('planned','executed','cancelled')), created_at TEXT NOT NULL, executed_at TEXT) STRICT;
